insert into public.collaboration_units(subject_id,unit_id) values ('algorithm','u2'),('algorithm','u3'),('algorithm','u4'),('algorithm','u6'),('algorithm','u7'),('os','u2'),('os','u3'),('os','u4'),('os','u5'),('os','u6') on conflict do nothing;
insert into public.builtin_question_targets(subject_id,unit_id,target_id,content) select subject_id,unit_id,target_id,content from jsonb_to_recordset('[{"subject_id":"algorithm","unit_id":"u2","target_id":1,"content":{"question":"遞迴式 T(n) = 2T(n/2) + cn 的漸進解為 __________。（請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,}）","options":[],"correct_answer":"big-theta(nlogn)","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":2,"content":{"question":"當問題規模 n > 1 時，合併排序法（Merge Sort）執行時間的遞迴關係式（Recurrence）為 T(n) = 2T(n/2) + __________。（請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,}）","options":[],"correct_answer":"big-theta(n)","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":3,"content":{"question":"對於任意整數 n，天花板函數與地板函數的相加關係式為：⌈ n/2 ⌉ + ⌊ n/2 ⌋ = __________。（請用英文小寫回答）","options":[],"correct_answer":"n","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":4,"content":{"question":"若滿足 m ≤ n 則 f(m) ≥ f(n)，此函數性質稱為 __________。（請用英文小寫回答，單字間留一空白）","options":[],"correct_answer":"monotonically decreasing","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":5,"content":{"question":"若滿足 m < n 則 f(m) < f(n)，此函數性質稱為 __________。（請用英文小寫回答，單字間留一空白）","options":[],"correct_answer":"strictly increasing","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":6,"content":{"question":"史特林近似公式（Stirling''s approximation）指出階乘 n! 的增長趨勢。寫成極限與漸進公式時，\\log(n!) = __________。（請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,}）","options":[],"correct_answer":"big-theta(nlogn)","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":7,"content":{"question":"史特林公式中指出，階乘 n! 的增長大於常數指數 2^n，即 n! = __________。（請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,}）","options":[],"correct_answer":"omega(2^n)","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":8,"content":{"question":"function fibonacci(n) { if (__________ ) { return 0; } else if (__________ ) { return 1; } int prev2 = 0; int prev1 = 1; int current = 0; for (int i = 2; i <= n; i++) { current = prev1 + prev2; prev2 = prev1; prev1 = current; } return current; }\n以上是計算費氏數列的函數 請正確地完成此程式 (用英文 變數要符合程式內的設定 填空格字裡不要有空白)","options":[],"correct_answer":"n<=0/n==1","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":9,"content":{"question":"若一個函數滿足 f(n) = __________，則稱此函數是多對數有界 (polylogarithmically bounded)。（請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^ 指數符號 用 k）","options":[],"correct_answer":"O(logn)^k","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":10,"content":{"question":"若一個函數滿足 f(n) = __________，則稱此函數是多項式有界。（請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^ 指數符號 用 k）","options":[],"correct_answer":"O(n^k)","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":11,"content":{"question":"在漸進符號中，表示 f(n) 最壞情況或上限為 __________，而表示最佳情況或下限為 __________。（請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,}）","options":[],"correct_answer":"第一格 O(f(n))，第二格 big-omega(f(n))","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":12,"content":{"question":"若一排序演算法在重排陣列時，最多僅需常數個額外記憶體空間在陣列外，此演算法被稱為 __________ 排序。（請用英文小寫回答，單字間留一空白）","options":[],"correct_answer":"in place","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":13,"content":{"question":"根據定理，f(n) = Θ(g(n)) 成立的充分且必要條件為下列哪些？","options":["A. f(n) = ω(g(n))","B. f(n) = o(g(n))","C. f(n) = Ω(g(n))","D. f(n) = O(g(n))"],"correct_answer":"C. f(n) = Ω(g(n))\nD. f(n) = O(g(n))","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":14,"content":{"question":"非漸進緊確的下界是用下列哪一個符號表示？","options":["A. ω","B. Ω","C. o","D. O"],"correct_answer":"A. ω","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":15,"content":{"question":"非漸進緊確的上界是用下列哪一個符號表示？","options":["A. O","B. Ω","C. ω","D. o"],"correct_answer":"D. o","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":16,"content":{"question":"漸進上界是用下列哪一個漸進符號表示？","options":["A. O","B. ω","C. Θ","D. Ω"],"correct_answer":"A. O","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":17,"content":{"question":"漸進緊確界是用下列哪一個漸進符號表示？","options":["A. Θ","B. O","C. Ω","D. o"],"correct_answer":"A. Θ","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":18,"content":{"question":"費氏數列（Fibonacci numbers）中定義的黃金比例 φ（Golden ratio）之近似值約為多少？","options":["A. 2.718","B. 1.618","C. 1.414","D. 3.141"],"correct_answer":"B. 1.618","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":19,"content":{"question":"在分析演算法時，我們常使用的單處理器隨機存取機器（RAM）模型中，做了哪些基礎假設？","options":["A. 每條基本指令（如加法、乘法、存取）花費常數時間","B. 所有數據都能隨機存取","C. 指令是逐一順序執行的（沒有並行運作）","D. 數據傳輸頻寬是無限大的"],"correct_answer":"A. 每條基本指令（如加法、乘法、存取）花費常數時間\nB. 所有數據都能隨機存取\nC. 指令是逐一順序執行的（沒有並行運作）","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":20,"content":{"question":"分治法通常包含下列哪些核心步驟？","options":["A. 回溯 (Backtrack)","B. 合併 (Combine)","C. 征服 (Conquer)","D. 分割 (Divide)"],"correct_answer":"B. 合併 (Combine)\nC. 征服 (Conquer)\nD. 分割 (Divide)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":21,"content":{"question":"插入排序法在最佳情況（Best-case）下的時間複雜度為何？","options":["A. O(n \\log n)","B. O(1)","C. O(n)","D. O(n^2)"],"correct_answer":"C. O(n)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":22,"content":{"question":"合併排序法採用的是下列哪一種演算法設計方法？","options":["A. 增量法 (Incremental Approach)","B. 分治法 (Divide-and-Conquer)","C. 貪婪法 (Greedy Approach)","D. 回溯法 (Backtracking)"],"correct_answer":"B. 分治法 (Divide-and-Conquer)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":23,"content":{"question":"合併排序法在最壞情況下的時間複雜度為何？","options":["A. O(n^2)","B. O(n \\log n)","C. O(n)","D. O(\\log n)"],"correct_answer":"B. O(n \\log n)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":24,"content":{"question":"關於費氏數列，下列定義與數學公式哪些是正確的？","options":["A. 當 i ≥ 2 時，F_i = F_{i-1} + F_{i-2}","B. 費氏數列隨指數級增長","C. F_0 = 0 且 F_1 = 1","D. F_i 可以用 φ（黃金比例）與其共軛值來精確表示"],"correct_answer":"A. 當 i ≥ 2 時，F_i = F_{i-1} + F_{i-2}\nB. 費氏數列隨指數級增長\nC. F_0 = 0 且 F_1 = 1\nD. F_i 可以用 φ（黃金比例）與其共軛值來精確表示","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":25,"content":{"question":"在合併排序法的合併步驟 Merge(A, p, q, r) 中，使用了哪些輔助常規？","options":["A. 完全不需要額外的記憶體空間","B. 在輔助陣列尾端放置無限大值（\\infty）作為哨兵（Sentinels）","C. 將排序結果複製回原陣列 A","D. 建立了兩個輔助陣列 L 和 R"],"correct_answer":"B. 在輔助陣列尾端放置無限大值（\\infty）作為哨兵（Sentinels）\nC. 將排序結果複製回原陣列 A\nD. 建立了兩個輔助陣列 L 和 R","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":26,"content":{"question":"下列關於漸進符號對稱性（Symmetry）與轉置對稱性（Transpose Symmetry）的敘述，哪些是正確的？","options":["A. f(n) = o(g(n)) 若且唯若 g(n) = ω(f(n))","B. f(n) = O(g(n)) 若且唯若 g(n) = O(f(n))","C. f(n) = Θ(g(n)) 若且唯若 g(n) = Θ(f(n))","D. f(n) = O(g(n)) 若且唯若 g(n) = Ω(f(n))"],"correct_answer":"A. f(n) = o(g(n)) 若且唯若 g(n) = ω(f(n))\nC. f(n) = Θ(g(n)) 若且唯若 g(n) = Θ(f(n))\nD. f(n) = O(g(n)) 若且唯若 g(n) = Ω(f(n))","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":27,"content":{"question":"關於漸進符號的遞移性，下列哪些選項是正確的？","options":["A. 若 f(n) = O(g(n)) 且 g(n) = O(h(n))，則 f(n) = O(h(n))","B. 若 f(n) = Ω(g(n)) 且 g(n) = Ω(h(n))，則 f(n) = Ω(h(n))","C. 若 f(n) = Θ(g(n)) 且 g(n) = Θ(h(n))，則 f(n) = Θ(h(n))","D. 若 f(n) = o(g(n)) 且 g(n) = o(h(n))，則 f(n) = o(h(n))"],"correct_answer":"A. 若 f(n) = O(g(n)) 且 g(n) = O(h(n))，則 f(n) = O(h(n))\nB. 若 f(n) = Ω(g(n)) 且 g(n) = Ω(h(n))，則 f(n) = Ω(h(n))\nC. 若 f(n) = Θ(g(n)) 且 g(n) = Θ(h(n))，則 f(n) = Θ(h(n))\nD. 若 f(n) = o(g(n)) 且 g(n) = o(h(n))，則 f(n) = o(h(n))","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":28,"content":{"question":"下列哪一個排序演算法是原地排序（Sorted in place），不需要額外的線性輔助空間？","options":["A. 合併排序 (Merge Sort)","B. 基數排序 (Radix Sort)","C. 插入排序 (Insertion Sort)","D. 計數排序 (Counting Sort)"],"correct_answer":"C. 插入排序 (Insertion Sort)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":29,"content":{"question":"若滿足 m ≤ n 則 f(m) ≤ f(n)，此函數性質為何者？","options":["A. 嚴格遞減 (Strictly decreasing)","B. 嚴格遞增 (Strictly increasing)","C. 單調遞增 (Monotonically increasing)","D. 單調遞減 (Monotonically decreasing)"],"correct_answer":"C. 單調遞增 (Monotonically increasing)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":30,"content":{"question":"下列漸進符號集合的數學定義，哪些是正確的？","options":["A. O(g(n)) 包含所有滿足 0 ≤ f(n) ≤ c * g(n) 的函數 f(n)（當 n ≥ n_0）","B. Ω(g(n)) 包含所有滿足 0 ≤ c * g(n) ≤ f(n) 的函數 f(n)（當 n ≥ n_0）","C. Θ(g(n)) 包含所有滿足 c_1 * g(n) ≤ f(n) ≤ c_2 * g(n) 的函數 f(n)（當 n ≥ n_0）","D. o(g(n)) 的極限關係為 \\lim \\frac{f(n)}{g(n)} = 0"],"correct_answer":"A. O(g(n)) 包含所有滿足 0 ≤ f(n) ≤ c * g(n) 的函數 f(n)（當 n ≥ n_0）\nB. Ω(g(n)) 包含所有滿足 0 ≤ c * g(n) ≤ f(n) 的函數 f(n)（當 n ≥ n_0）\nC. Θ(g(n)) 包含所有滿足 c_1 * g(n) ≤ f(n) ≤ c_2 * g(n) 的函數 f(n)（當 n ≥ n_0）\nD. o(g(n)) 的極限關係為 \\lim \\frac{f(n)}{g(n)} = 0","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":31,"content":{"question":"下列關於階乘增長率的漸進關係，哪些選項是正確的？","options":["A. \\log(n!) = Θ(n \\log n)","B. n! = O(2^n)","C. n! = ω(2^n)","D. n! = o(n^n)"],"correct_answer":"A. \\log(n!) = Θ(n \\log n)\nC. n! = ω(2^n)\nD. n! = o(n^n)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":32,"content":{"question":"關於重複對數函數 \\lg^* n，下列敘述哪些是正確的？","options":["A. 在可觀測宇宙中幾乎遇不到 n 使得 \\lg^* n > 5","B. 它是極度緩慢增長的函數","C. \\lg^* 65536 = 4","D. \\lg^* 2 = 1"],"correct_answer":"A. 在可觀測宇宙中幾乎遇不到 n 使得 \\lg^* n > 5\nB. 它是極度緩慢增長的函數\nC. \\lg^* 65536 = 4\nD. \\lg^* 2 = 1","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":33,"content":{"question":"重複對數函數值 \\lg^* 4 的結果為多少？","options":["A. 1","B. 2","C. 3","D. 4"],"correct_answer":"B. 2","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":34,"content":{"question":"重複對數函數值 \\lg^* 16 的結果為多少？","options":["A. 1","B. 2","C. 3","D. 4"],"correct_answer":"C. 3","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":35,"content":{"question":"演算法分析中，通常專注於尋找「最壞情況執行時間」的原因有哪些？","options":["A. 最壞情況發生的頻率在實際應用中相當高","B. 平均情況往往和最壞情況一樣糟（例如插入排序）","C. 它最容易被計算出精確的常數項","D. 它提供了執行時間的保證上限（Upper Bound）"],"correct_answer":"A. 最壞情況發生的頻率在實際應用中相當高\nB. 平均情況往往和最壞情況一樣糟（例如插入排序）\nD. 它提供了執行時間的保證上限（Upper Bound）","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":36,"content":{"question":"對於任何常數 a > 1，當 n 趨近於無窮大時，多項式函數與指數函數的關係極限值為 (n^b / a^n)？","options":["A. 0(zero)","B. 無窮大 (Infinity)","C. Undefined","D. 1(one)"],"correct_answer":"A. 0(zero)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":37,"content":{"question":"在計算機科學中，若無特別註明，常數「\\lg n」通常表示以下列哪一個數為底的對數？","options":["A. 2","B. Infinity","C. e","D. 10"],"correct_answer":"A. 2","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":38,"content":{"question":"關於插入排序法的迴圈不變量（Loop Invariant），下列敘述哪些是正確的？","options":["A. 子陣列 A[j \\,..\\, n] 中的元素是已排序的","B. 子陣列 A[1 \\,..\\, j-1] 中的元素是已排序的","C. 在每輪 for 迴圈開始時，子陣列 A[1 \\,..\\, j-1] 由原本的 A[1 \\,..\\, j-1] 元素組成","D. 此不變量可用於證明演算法的正確性"],"correct_answer":"B. 子陣列 A[1 \\,..\\, j-1] 中的元素是已排序的\nC. 在每輪 for 迴圈開始時，子陣列 A[1 \\,..\\, j-1] 由原本的 A[1 \\,..\\, j-1] 元素組成\nD. 此不變量可用於證明演算法的正確性","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":39,"content":{"question":"關於函數增長率的比較，下列哪些敘述是正確的？","options":["A. 任何正多項式函數增長速度都快於任何多對數（Polylogarithmic）函數","B. 任何正指數函數增長速度都快於任何多項式函數","C. n \\log n 增長速度快於 n^2","D. 對數函數增長快於階乘函數"],"correct_answer":"A. 任何正多項式函數增長速度都快於任何多對數（Polylogarithmic）函數\nB. 任何正指數函數增長速度都快於任何多項式函數","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":40,"content":{"question":"對於所有 x > -1，下列關於對數函數（Logarithm）的數學不等式哪些是正確的？","options":["A. \\ln(1 + x) < x","B. \\ln(1 + x) = x - x^2/2 + x^3/3 - x^4/4 + \\dots（當 |x| < 1）","C. x / (1 + x) ≤ \\ln(1 + x)","D. \\ln(1 + x) > x"],"correct_answer":"x / (1 + x) <= ln(1 + x)\nln(1 + x) < x\nln(1 + x) = x - x²/2 + x³/3 - x⁴/4 + ... (當 |x| < 1)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":41,"content":{"question":"大於或等於實數 x 的最小整數是用下列哪一個函數表示？","options":["四捨五入 (Round)","地板函數 (Floor)","絕對值 (Absolute)","天花板函數 (Ceiling)"],"correct_answer":"天花板函數 (Ceiling)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":42,"content":{"question":"階乘增長率與指數增長率相比，n! 屬於 o(nⁿ)，但與常見的 2ⁿ 指數相比，n! 屬於 [__1__]\n關係。(請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta,\nbig-omega, omega, O, o,})","options":[],"correct_answer":"omega(2^n)","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":43,"content":{"question":"對於所有實數 x，下列關於指數函數的性質哪些是正確的？","options":["1. 1 + x ≤ e^x","2. 當 |x| ≤ 1 時，e^x ≤ 1 + x + x²/2","3. lim(n→∞) (1 + x/n)^n = e^x","4. e^x 永遠小於 1"],"correct_answer":"1. 1 + x ≤ e^x\n2. 當 |x| ≤ 1 時，e^x ≤ 1 + x + x²/2\n3. lim(n→∞) (1 + x/n)^n = e^x","type":"disputed"}},{"subject_id":"algorithm","unit_id":"u2","target_id":44,"content":{"question":"插入排序法（Insertion Sort）在最壞情況（Worst-case）下的時間複雜度為何？","options":["O(n log n)","O(2^n)","O(n^2)","O(n)"],"correct_answer":"O(n^2)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":45,"content":{"question":"漸進下界（Asymptotic lower bound）是用下列哪一個漸進符號表示？","options":["O","Ω","Θ","o"],"correct_answer":"Ω","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":46,"content":{"question":"小於或等於實數 x 的最大整數是用下列哪一個函數表示？","options":["A. 地板函數（Floor）"],"correct_answer":"A. 地板函數（Floor）","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":47,"content":{"question":"插入排序法（Insertion Sort）採用的是下列哪一種演算法設計方法？","options":["增量法 (Incremental Approach)","貪婪演算法 (Greedy Algorithm)","動態規劃 (Dynamic Programming)","分治法 (Divide-and-Conquer)"],"correct_answer":"增量法 (Incremental Approach)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":48,"content":{"question":"下列哪些函數屬於多對數有界（Polylogarithmically bounded）的範疇？","options":["f(n) = (lg n)^2","f(n) = (lg n)^5","f(n) = lg(lg n)","f(n) = n"],"correct_answer":"f(n) = (lg n)^2\nf(n) = (lg n)^5\nf(n) = lg(lg n)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":49,"content":{"question":"分析演算法（Analyzing algorithms）時，通常需要預測演算法所需的哪些資源？","options":["A. 執行時間（Time）","B. 記憶體空間（Memory）","C. 網路頻寬（Communication bandwidth）","D. 邏輯閘數量（Logic gates）"],"correct_answer":"A. 執行時間（Time）\nB. 記憶體空間（Memory）\nC. 網路頻寬（Communication bandwidth）\nD. 邏輯閘數量（Logic gates）","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":50,"content":{"question":"插入排序法的最壞情況執行時間是 n 的[__1__]函數，最佳情況執行時間是 n 的[__2__]函數(要用最嚴謹的答案回答)。(請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,})","options":[],"correct_answer":"big-theta(n^2)/big-theta(n)","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":51,"content":{"question":"漸進上界與下界的轉換：f(n) = O(g(n)) 若且唯若 g(n) = [__1__]。(請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,})","options":[],"correct_answer":"big-omega(f(n))","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":52,"content":{"question":"若一函數 f(n) 滿足 f(n) = n⁽ᴼ⁽¹⁾⁾，則此函數稱為多項式有界（Polynomial bounded）。下列哪些屬於此類別？","options":["A. f(n) = n³","B. f(n) = 10n² + 5n","C. f(n) = √n","D. f(n) = 2ⁿ"],"correct_answer":"A. f(n) = n³\nB. f(n) = 10n² + 5n\nC. f(n) = √n","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":53,"content":{"question":"Insertion-Sort(A)\n1  for j ← 2 to length[A]\n2    do key ← A[j]\n3       // Insert A[j] into the sorted sequence A[1 .. j - 1]\n4       i ← j - 1\n5       while i > 0 and A[i] > key\n6         do A[i + 1] ← A[i]\n7            i ← i - 1\n8       A[i + 1] ← key\n\n\n以上 為 insertion sort 的演算法 請問\n令A 長度為n , 每一行的執行成本都是 1 \n若第5行 每次都執行1次 請問這個程式執行的成本是多少[__1__] (答案用到英文字母請用小寫 裡面部要有空白)","options":[],"correct_answer":"5n-4","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":54,"content":{"question":"我們使用[__1__]（請填二個字的英文單字）來證明演算法的正確性。在迴圈每次迭代開始時，子序列的特定性質都保持不變。(請用英文小寫回答，單字間留一空白)","options":[],"correct_answer":"loop invariant","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":55,"content":{"question":"當一個函數 f(n) 同時滿足 O(g(n)) 且 Ω(g(n)) 時，我們說 g(n) 是 f(n) 的漸進緊確界，其符號為 [__1__]。(請用英文回答，表示形式為 請用log，不可用lg替代log，上標請用^，符號請用 {big-theta, theta, big-omega, omega, O, o,})","options":[],"correct_answer":"big-theta(g(n))","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":56,"content":{"question":"關於模運算（Modular arithmetic），下列哪些數學公式或關係是正確的？","options":["A. a mod n = a − ⌊a/n⌋ × n","B. 若 a mod n = b mod n，則 a ≡ b (mod n)","C. a mod n 代表 a 除以 n 的餘數","D. a ≡ b (mod n) 表示兩者模 n 同餘"],"correct_answer":"A. a mod n = a − ⌊a/n⌋ × n\nB. 若 a mod n = b mod n，則 a ≡ b (mod n)\nC. a mod n 代表 a 除以 n 的餘數\nD. a ≡ b (mod n) 表示兩者模 n 同餘","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":57,"content":{"question":"表示重複對數函數（Iterative logarithm function）的數學寫法為 [__1__]。(請用小寫英文回答)","options":[],"correct_answer":"lg*(n)","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":58,"content":{"question":"對於任意實數 x 或整數 n，下列關於地板與天花板函數的數學性質哪些是正確的？（D 選項中的 a、b 為正整數。）","options":["⌈n/2⌉ + ⌊n/2⌋ = n","x - 1 < ⌊x⌋ <= x","x <= ⌈x⌉ < x + 1","⌊⌊n/a⌋/b⌋ = ⌊n/(ab)⌋"],"correct_answer":"⌈n/2⌉ + ⌊n/2⌋ = n\nx - 1 < ⌊x⌋ <= x\nx <= ⌈x⌉ < x + 1\n⌊⌊n/a⌋/b⌋ = ⌊n/(ab)⌋","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":59,"content":{"question":"史特林近似公式（Stirling''s approximation）主要用於估算下列哪一種數學函數的增長？","options":["A. 階乘函數（Factorial）","B. 對數函數（Logarithm）"],"correct_answer":"A. 階乘函數（Factorial）","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":60,"content":{"question":"分治法將問題分解成子問題，遞迴求解。其三個主要動作分別為：[__1__]、[__2__]、[__3__]。(請用小寫英文回答)","options":[],"correct_answer":"divide/conquer/combine","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":61,"content":{"question":"非漸進緊確的上界（Upper bound that is not asymptotically tight）是用哪一個符號表示？","options":["O","Ω","o","Θ"],"correct_answer":"o","type":"choice"}},{"subject_id":"algorithm","unit_id":"u2","target_id":62,"content":{"question":"lg* 4 = [__1__]。","options":[],"correct_answer":"2","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u2","target_id":63,"content":{"question":"Merge Sort 在最壞情況下的時間複雜度為何？","options":["O(n)","O(n log n)","O(n^2)","O(2^n)"],"correct_answer":"O(n log n)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u3","target_id":1,"content":{"question":"遞迴樹法在下列哪些情況下特別有用？","options":["當 f(n) 在遞迴樹中變化時","當需要產生好的猜測時","當使用代入法過於複雜時","當遞迴樹非常對稱時"],"correct_answer":"當 f(n) 在遞迴樹中變化時\n當需要產生好的猜測時\n當使用代入法過於複雜時\n當遞迴樹非常對稱時","type":"choice"}},{"subject_id":"algorithm","unit_id":"u3","target_id":2,"content":{"question":"當遞迴式包含下取整或上取整時，我們通常？","options":["忽略它們","將其改為指數","將其改為絕對值","將其改為階乘"],"correct_answer":"忽略它們","type":"choice"}},{"subject_id":"algorithm","unit_id":"u3","target_id":3,"content":{"question":"在處理 T(n) = 2T(n/2 + 17) + n 時，我們通常使用？","options":["陣列平移","代入法","圖形繪製","硬編碼"],"correct_answer":"代入法","type":"choice"}},{"subject_id":"algorithm","unit_id":"u3","target_id":4,"content":{"question":"關於大師定理 (Master Method) 的限制，下列敘述何者正確？","options":["無法判斷分治代價 f(n) 的情況","適用於所有遞迴式","必須滿足 a >= 1 及 b > 1","不能用於 f(n) 與 n^(log_b(a)) 成長率相差非多項式的情況"],"correct_answer":"必須滿足 a >= 1 及 b > 1\n不能用於 f(n) 與 n^(log_b(a)) 成長率相差非多項式的情況","type":"choice"}},{"subject_id":"algorithm","unit_id":"u3","target_id":5,"content":{"question":"大師定理中，若 f(n) 成長速度慢於 O(nˡᵒᵍᵇ⁽ᵃ⁾)，則複雜度為？","options":["O(nˡᵒᵍᵇ⁽ᵃ⁾)","O(n)","O(f(n))"],"correct_answer":"O(nˡᵒᵍᵇ⁽ᵃ⁾)","type":"choice"}},{"subject_id":"algorithm","unit_id":"u3","target_id":6,"content":{"question":"當 f(n) 在大師定理中成長速度大於 nˡᵒᵍᵇ⁽ᵃ⁾ 時，我們稱之為 Case [__1__] (請用小寫英文回答)","options":[],"correct_answer":"three","type":"fill_blank"}},{"subject_id":"algorithm","unit_id":"u3","target_id":7,"content":{"question":"在使用代入法時，常遇到的困難包含？","options":["證明邊界條件的繁瑣","無法進行代數變換","遞迴樹過於龐大","猜測解的正確形式"],"corr